<?php
namespace MarinePortal\Email;
use GuzzleHttp\Client;
class SendGridDriver implements EmailInterface { public function __construct(private array $cfg, private string $from, private string $replyTo=''){} public function send(string $to, string $subject, string $html, ?string $text=null, array $opts=[]): bool { if(empty($this->cfg['api_key'])) return false; $c=new Client(); $payload=['personalizations'=>[['to'=>[['email'=>$to]]]],'from'=>['email'=>$this->parseEmail($this->from)],'subject'=>$subject,'content'=>[['type'=>'text/html','value'=>$html]]]; try{ $r=$c->post('https://api.sendgrid.com/v3/mail/send',['headers'=>['Authorization'=>"Bearer {$this->cfg['api_key']}"],'json'=>$payload]); return $r->getStatusCode()<300; }catch(\Throwable $e){ error_log($e->getMessage()); return false; } } private function parseEmail($f){ if(preg_match('/<(.*?)>/',$f,$m)) return $m[1]; return $f; } }
